.primario{background:var(--laranja);color:#fff;box-shadow:0 10px 22px -12px rgba(232,123,35,.95)}
.primario:hover:not(:disabled){transform:translateY(-2px);filter:brightness(1.05)}
.fantasma{background:transparent;color:var(--azul-marca);border:2px solid var(--papel-borda)}
.fantasma:hover:not(:disabled){background:rgba(27,78,155,.07)}
.acoes{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px;align-items:center}
.aviso{margin-top:18px;border-radius:12px;padding:13px 15px;font-size:13.5px;font-weight:500;
  border:2px solid rgba(232,123,35,.35);background:rgba(232,123,35,.09)}

/* lotação */
.painel-lotado{position:relative;margin-top:24px;padding:clamp(24px,3.6vw,30px) clamp(18px,3.2vw,28px) clamp(20px,3vw,26px);
  border:2px solid rgba(194,52,31,.32);border-radius:14px;
  background:linear-gradient(180deg,rgba(255,255,255,.72),rgba(232,123,35,.11));
  box-shadow:0 18px 36px -28px rgba(30,42,58,.85)}
.painel-lotado::before{content:'';position:absolute;top:-11px;left:50%;width:104px;height:22px;background:var(--fita);
  transform:translateX(-50%) rotate(-1.6deg);box-shadow:0 1px 3px rgba(0,0,0,.16)}
.painel-lotado .selo{position:absolute;top:-17px;right:clamp(14px,4vw,28px);
  font-weight:800;font-size:clamp(14px,2.8vw,18px);letter-spacing:.08em;text-transform:uppercase;
  color:rgba(194,52,31,.9);border:4px solid rgba(194,52,31,.9);border-radius:9px;padding:5px 14px;
  background:var(--papel);transform:rotate(-9deg)}
.painel-lotado h3{margin:4px 0 0;padding-right:104px;font-size:clamp(20px,3.8vw,28px);color:var(--azul-marca);letter-spacing:-.02em}
.painel-lotado p{margin:11px 0 0;max-width:60ch;font-size:14.5px;line-height:1.62;font-weight:500;color:var(--tinta)}
.painel-lotado p.dica{font-size:13.5px;color:var(--tinta-fraca)}
.painel-lotado .fechamento{font-family:'Caveat',cursive;font-weight:700;font-size:22px;line-height:1.25;
  color:var(--azul-escuro);margin-top:15px;transform:rotate(-.5deg)}

.mural-topo{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;flex-wrap:wrap}
.contador{font-weight:800;font-size:clamp(50px,12vw,84px);line-height:.9;color:var(--azul-marca);letter-spacing:-.04em}
.contador .limite{font-size:.4em;color:var(--tinta-fraca)}
.contador-rot{font-weight:700;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--tinta-fraca);margin-top:8px}
.barra{width:clamp(160px,48vw,290px);height:11px;margin-top:14px;border-radius:99px;
  background:var(--papel-som);border:1px solid var(--papel-borda);overflow:hidden}
.barra i{display:block;height:100%;width:0;border-radius:99px;
  background:linear-gradient(90deg,var(--laranja),#F5A44E);transition:width .6s cubic-bezier(.2,.8,.3,1)}
.barra.cheia i{background:linear-gradient(90deg,var(--erro),#D9553C)}
.vagas{margin-top:9px;font-size:13.5px;font-weight:600;color:var(--tinta-fraca)}
.vagas.alerta{color:var(--laranja)}
.vagas.esgotado{color:var(--erro)}
.mural{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:18px;margin-top:26px}
.mural .postit{min-height:122px;transition:transform .18s}
.mural .postit:hover{transform:rotate(0) translateY(-4px) scale(1.03);z-index:3}
.nome-cracha{font-size:23px;line-height:1.08}
.extra-cracha{font:600 12px 'Montserrat',sans-serif;color:rgba(21,59,122,.72);margin-top:9px;line-height:1.35}
.vazio{margin-top:24px;border:2px dashed var(--papel-borda);border-radius:14px;padding:32px;text-align:center;color:var(--tinta-fraca);font-weight:500}

.carimbo{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;z-index:40;pointer-events:none}
.carimbo b{font-family:'Montserrat',sans-serif;font-weight:800;font-size:clamp(38px,11vw,86px);letter-spacing:.04em;
  color:rgba(194,52,31,.88);border:8px solid rgba(194,52,31,.88);border-radius:12px;padding:12px 28px;
  transform:rotate(-13deg);animation:carimbar 1.35s ease-out forwards}
@keyframes carimbar{0%{opacity:0;transform:rotate(-13deg) scale(2.4)}22%,72%{opacity:1;transform:rotate(-13deg) scale(1)}100%{opacity:0;transform:rotate(-13deg) scale(1.05)}}
